"""T-025: the datapack part of the Garden of Silence, written by tools/build/r1_garden.py: function/garden/gen/*. Generated, do not edit.
The hand-written logic is function/garden/*.mcfunction and function/creak/*.mcfunction.

Scores (objective le.gd): #h<k> heart k alive (1) / destroyed (0), #left hearts left, #asleep 0/1, #key 0 not built / 1 on the pedestal /
2 taken, #stand 0/1 the show stand built, #sc<s> gametime when sensor s may wake again, #gcd the cooldown of the whole garden,
#gt gametime, #t ticks of the loop. Storage last_ember:garden {h:{h1..h6}, asleep, key} mirrors them (survives a reset of scores).
Creakings of the sensors: tag le.garden_cr, score le.gdt = gametime when they crumble."""
import math, os

def run(R, meta):
    GEN = os.path.join(R.DP, "function/garden/gen")
    os.makedirs(GEN, exist_ok=True)
    for root, _, fs in os.walk(GEN):
        for f in fs:
            if f.endswith(".mcfunction"): os.remove(os.path.join(root, f))
    for sub in ("b", "f"): os.makedirs(os.path.join(GEN, sub), exist_ok=True)
    hdr = "# generated by tools/build/r1_garden.py (garden_dp.py): "
    def w(name, lines): open(os.path.join(GEN, name + ".mcfunction"), "w", encoding="utf-8").write("\n".join(lines) + "\n")
    def st(s): return s if s.startswith("minecraft:") else "minecraft:" + s
    x1, z1, x2, z2 = R.CORE[0] - 16, R.CORE[1] - 16, R.CORE[2] + 16, R.CORE[3] + 16
    GBOX = "x=%d,y=30,z=%d,dx=%d,dy=200,dz=%d" % (x1, z1, x2 - x1, z2 - z1)
    NBOX = "x=%d,y=-64,z=%d,dx=%d,dy=384,dz=%d" % (x1 - 32, z1 - 32, x2 - x1 + 64, z2 - z1 + 64)
    hearts, faces, sens, blooms = meta["hearts"], meta["faces"], meta["sensors"], meta["blooms"]
    # ---- init, boxes
    L = [hdr + "defaults of the state (only where nothing is set: a reload keeps it), from the storage when the scores were lost"]
    for h in hearts:
        k = h["id"]
        L.append("execute unless score #h%d le.gd = #h%d le.gd store result score #h%d le.gd run data get storage last_ember:garden h.h%d" % (k, k, k, k))
    for nm in ("asleep", "key"):
        L.append("execute unless score #%s le.gd = #%s le.gd store result score #%s le.gd run data get storage last_ember:garden %s" % (nm, nm, nm, nm))
    L.append("execute unless data storage last_ember:garden h run function last_ember:garden/gen/fresh")
    L.append("execute unless score #gcd le.gd = #gcd le.gd run scoreboard players set #gcd le.gd 0")
    for s in sens: L.append("execute unless score #sc%d le.gd = #sc%d le.gd run scoreboard players set #sc%d le.gd 0" % (s["id"], s["id"], s["id"]))
    L.append("scoreboard players set #stand le.gd 0")
    L.append("function last_ember:garden/gen/count")
    w("init", L)
    w("fresh", [hdr + "a new world: 6 living hearts, the garden awake, the key not built yet"] + ["scoreboard players set #h%d le.gd 1" % h["id"] for h in hearts] +
      ["scoreboard players set #asleep le.gd 0", "scoreboard players set #key le.gd 0",
       "data modify storage last_ember:garden h set value {%s}" % ",".join("h%d:1b" % h["id"] for h in hearts),
       "data modify storage last_ember:garden asleep set value 0b", "data modify storage last_ember:garden key set value 0b"])
    w("count", [hdr + "#left = living hearts", "scoreboard players set #left le.gd 0"] +
      ["scoreboard players operation #left le.gd += #h%d le.gd" % h["id"] for h in hearts])
    w("in_garden", [hdr + "as an entity: 1 when it stands in the garden (the place with its seam)", "execute if entity @s[%s] run return 1" % GBOX, "return 0"])
    w("creakings", [hdr + "#ncr = creakings in the garden", "execute store result score #ncr le.gd if entity @e[type=minecraft:creaking,%s]" % GBOX])
    w("near", [hdr + "#near = players (not spectators) in the garden or within 32 of it", "execute store result score #near le.gd if entity @a[%s,gamemode=!spectator]" % NBOX])
    w("away", [hdr + "the sensor creakings crumble when no player is within 32 of the garden",
               "execute unless entity @a[%s,gamemode=!spectator] as @e[type=minecraft:creaking,tag=le.garden_cr] at @s run function last_ember:garden/crumble" % NBOX])
    w("crumble_all", [hdr + "the garden falls asleep: every creaking in it crumbles",
                      "execute as @e[type=minecraft:creaking,%s] at @s run function last_ember:garden/crumble" % GBOX])
    # ---- hearts
    L = [hdr + "every second: a living heart whose block is gone is destroyed for good (only when its chunk is loaded)"]
    for h in hearts:
        L.append("execute if score #h%d le.gd matches 1 if loaded %d %d %d unless block %d %d %d minecraft:creaking_heart run function last_ember:garden/gen/lost_%d" %
                 (h["id"], h["x"], h["y"], h["z"], h["x"], h["y"], h["z"], h["id"]))
        w("lost_%d" % h["id"], [hdr + "heart %d (%s) destroyed" % (h["id"], h["kind"]), "scoreboard players set #h%d le.gd 0" % h["id"],
                                "data modify storage last_ember:garden h.h%d set value 0b" % h["id"],
                                "execute positioned %d %d %d run function last_ember:garden/heart_lost" % (h["x"], h["y"], h["z"])])
    w("hearts", L)
    w("hearts_status", [hdr + "TEST/ADMIN: the hearts in the chat"] +
      ['tellraw @s [{"text":"сердце %d (%s) %d %d %d: "},{"score":{"name":"#h%d","objective":"le.gd"}}]' % (h["id"], h["kind"], h["x"], h["y"], h["z"], h["id"]) for h in hearts])
    w("hearts_restore", [hdr + "TEST/ADMIN: the 6 hearts back in their trunks, all alive, the garden awake (faces follow by themselves)"] +
      ["setblock %d %d %d minecraft:creaking_heart[axis=y,creaking_heart_state=dormant,natural=true]" % (h["x"], h["y"], h["z"]) for h in hearts] +
      ["function last_ember:garden/gen/fresh", "data modify storage last_ember:garden key set from storage last_ember:garden key", "function last_ember:garden/gen/count"])
    # ---- faces
    L = [hdr + "every second: the 12 carved faces follow the night (towards the orangery, eyes open) and the day / the sleep (outward, eyes closed),"
              " but only when no player within 24 looks at them (angle <= 70 degrees); chunk loaded"]
    for f in faces:
        L.append("execute if loaded %d %d %d run function last_ember:garden/gen/f/%d" % (f["x"] + 1, f["base"], f["z"] + 1, f["id"]))
    w("faces", L)
    for f in faces:
        k = f["id"]; x, z, base = f["x"], f["z"], f["base"]; d = tuple(f["out"]); din = (-d[0], -d[1])
        side_in, _ = R.face_cells(x, z, base, din)
        px, pz = side_in[0]
        cx, cy, cz = x + 1.5, base + 3.5, z + 1.5
        w("f/%d" % k, [hdr + "carved face %d (%s) at %d %d, outward %s: #fw wanted (1 = night: in), #fc what stands (inward eye open = in)" % (k, f["kind"], x, z, d),
                       "scoreboard players set #fw le.gd 0",
                       "execute if score #asleep le.gd matches 0 if predicate last_ember:night run scoreboard players set #fw le.gd 1",
                       "scoreboard players set #fc le.gd 0",
                       "execute if block %d %d %d minecraft:pale_oak_wood run scoreboard players set #fc le.gd 1" % (px, base + 3, pz),
                       "execute if score #fw le.gd = #fc le.gd run return 0",
                       "execute positioned %.1f %.1f %.1f as @a[distance=..24,gamemode=!spectator] at @s anchored eyes facing %.1f %.1f %.1f anchored feet positioned ^ ^ ^1 rotated as @s positioned ^ ^ ^-1 if entity @s[distance=..1.147] run return 0" % (cx, cy, cz, cx, cy, cz),
                       "execute if score #fw le.gd matches 1 run return run function last_ember:garden/gen/f/%d_in" % k,
                       "function last_ember:garden/gen/f/%d_out" % k])
        blk_in = dict(R.bark_blocks(x, z, base, d)); blk_in.update(R.face_blocks(x, z, base, din, "open"))
        blk_out = dict(R.bark_blocks(x, z, base, din)); blk_out.update(R.face_blocks(x, z, base, d, "closed"))
        snd = "playsound minecraft:block.creaking_heart.idle block @a[distance=..24] %.1f %.1f %.1f 0.5 0.6" % (cx, cy, cz)
        # bark first (it clears the trapdoors of the other side), then the face
        def order(dct, side_d):
            bark = [(p, s) for p, s in dct.items() if s.startswith("minecraft:pale_oak_log") or s == "minecraft:air"]
            rest = [(p, s) for p, s in dct.items() if (p, s) not in bark]
            return bark + rest
        w("f/%d_in" % k, [hdr + "face %d to the orangery, eyes open" % k] + ["setblock %d %d %d %s" % (p + (s,)) for p, s in order(blk_in, din)] + [snd])
        w("f/%d_out" % k, [hdr + "face %d outward, eyes closed" % k] + ["setblock %d %d %d %s" % (p + (s,)) for p, s in order(blk_out, d)] + [snd])
    # ---- sensors
    L = [hdr + "every 5 ticks while somebody is near the garden and it is awake: an active sensor (sculk_sensor_phase=active) off its cooldown wakes"]
    for s in sens:
        L.append("execute if score #gt le.gd >= #sc%d le.gd if block %d %d %d minecraft:sculk_sensor[sculk_sensor_phase=active] run function last_ember:garden/gen/sn%d" % (s["id"], s["x"], s["y"], s["z"], s["id"]))
        w("sn%d" % s["id"], [hdr + "sensor %d at %d %d %d went off: 2 creakings behind the nearest player (10..16 from the sensor), cooldowns 60 s / 20 s" % (s["id"], s["x"], s["y"], s["z"]),
                             "# vanilla sets a sensor off by any foot on it, sneaking too (SculkSensorBlock.stepOn): a sneaking player on the carpet over it",
                             "# does not wake the garden (the rest of this activation, 2 s, is skipped)",
                             "execute if entity @a[x=%d,y=%d,z=%d,dx=0,dy=0,dz=0,predicate=last_ember:sneaking] run scoreboard players operation #sc%d le.gd = #gt le.gd" % (s["x"], s["y"] + 1, s["z"], s["id"]),
                             "execute if entity @a[x=%d,y=%d,z=%d,dx=0,dy=0,dz=0,predicate=last_ember:sneaking] run return run scoreboard players add #sc%d le.gd 40" % (s["x"], s["y"] + 1, s["z"], s["id"]),
                             "execute if score #gt le.gd < #gcd le.gd run return 0",
                             "function last_ember:garden/gen/creakings",
                             "execute if score #ncr le.gd matches 6.. run return 0",
                             "execute positioned %d %d %d unless entity @a[distance=..24,gamemode=!spectator,gamemode=!creative] run return 0" % (s["x"], s["y"], s["z"]),
                             "summon minecraft:marker %.1f %.1f %.1f {Tags:[\"le.gsn\"]}" % (s["x"] + 0.5, s["y"] + 0.5, s["z"] + 0.5),
                             "scoreboard players set #wk le.gd 0",
                             "execute positioned %d %d %d as @p[distance=..24,gamemode=!spectator,gamemode=!creative] at @s run function last_ember:garden/wake" % (s["x"], s["y"], s["z"]),
                             "kill @e[type=minecraft:marker,tag=le.gsn]",
                             "execute if score #wk le.gd matches 0 run return 0",
                             "scoreboard players operation #sc%d le.gd = #gt le.gd" % s["id"], "scoreboard players add #sc%d le.gd 1200" % s["id"],
                             "scoreboard players operation #gcd le.gd = #gt le.gd", "scoreboard players add #gcd le.gd 400"])
    w("sensors", L)
    # ---- eyeblossoms (after the sleep): by squares of 64, only loaded and with a player near
    groups = {}
    for (x, y, z) in blooms: groups.setdefault((x // 64, z // 64), []).append((x, y, z))
    L = [hdr + "every 10 ticks after the garden fell asleep: the open eyeblossoms of the garden close again (%d points in %d squares)" % (len(blooms), len(groups))]
    for (gx, gz), pts in sorted(groups.items()):
        xs = [p[0] for p in pts]; zs = [p[2] for p in pts]
        L.append("execute if loaded %d 0 %d if loaded %d 0 %d if entity @a[x=%d,y=-64,z=%d,dx=%d,dy=384,dz=%d] run function last_ember:garden/gen/b/%d_%d" %
                 (min(xs), min(zs), max(xs), max(zs), min(xs) - 48, min(zs) - 48, max(xs) - min(xs) + 96, max(zs) - min(zs) + 96, gx, gz))
        w("b/%d_%d" % (gx, gz), [hdr + "eyeblossoms of the square %d %d" % (gx, gz)] +
          ["execute if block %d %d %d minecraft:open_eyeblossom run setblock %d %d %d minecraft:closed_eyeblossom" % (x, y, z, x, y, z) for (x, y, z) in pts])
    w("blooms", L)
    w("blooms_open", [hdr + "TEST: all eyeblossoms of the list open"] + ["execute if block %d %d %d minecraft:closed_eyeblossom run setblock %d %d %d minecraft:open_eyeblossom" % (x, y, z, x, y, z) for (x, y, z) in blooms])
    w("blooms_count", [hdr + "TEST: #bo = open, #bc = closed eyeblossoms of the list (loaded chunks)", "scoreboard players set #bo le.gd 0", "scoreboard players set #bc le.gd 0"] +
      ["execute if block %d %d %d minecraft:open_eyeblossom run scoreboard players add #bo le.gd 1\nexecute if block %d %d %d minecraft:closed_eyeblossom run scoreboard players add #bc le.gd 1" % (x, y, z, x, y, z) for (x, y, z) in blooms])
    # ---- the door of the house, the key, the stand
    dx, dy, dz = meta["door"]
    w("door_shut", [hdr + "the door of the house is locked while the garden is awake: shut again at once",
                    "setblock %d %d %d minecraft:pale_oak_door[facing=north,half=lower,hinge=left,open=false,powered=false]" % (dx, dy, dz),
                    "setblock %d %d %d minecraft:pale_oak_door[facing=north,half=upper,hinge=left,open=false,powered=false]" % (dx, dy + 1, dz),
                    "playsound minecraft:block.chest.locked block @a[distance=..16] %d %d %d 1 0.8" % (dx, dy, dz)])
    w("door_check", [hdr + "every second (and on every use): the locked door stands shut",
                     "execute if score #asleep le.gd matches 0 if loaded %d %d %d if block %d %d %d minecraft:pale_oak_door[open=true] run function last_ember:garden/gen/door_shut" % (dx, dy, dz, dx, dy, dz)])
    kx, ky, kz = meta["key"]
    w("key_build", [hdr + "the Tear of the Creaker on its pedestal (item_display) + a click box (interaction)",
                    "kill @e[type=minecraft:item_display,tag=le.gdkey_disp]", "kill @e[type=minecraft:interaction,tag=le.gdkey]",
                    'summon minecraft:item_display %.1f %.2f %.1f {Tags:["le.gdkey_disp"],item:{id:"minecraft:ominous_trial_key",count:1,components:{"minecraft:item_model":"last_ember:key_tear_creaker"}},billboard:"fixed",transformation:{left_rotation:[0f,0f,0f,1f],right_rotation:[0f,0f,0f,1f],translation:[0f,0f,0f],scale:[0.7f,0.7f,0.7f]},brightness:{sky:12,block:12}}' % (kx + 0.5, ky + 0.6, kz + 0.5),
                    'summon minecraft:interaction %.1f %d %.1f {Tags:["le.gdkey"],width:1.1f,height:1.3f,response:1b}' % (kx + 0.5, ky, kz + 0.5),
                    "scoreboard players set #key le.gd 1", "data modify storage last_ember:garden key set value 1b"])
    w("key_check", [hdr + "every second: the key stands on its pedestal until it is taken",
                    "execute if score #key le.gd matches 0 if loaded %d %d %d run function last_ember:garden/gen/key_build" % (kx, ky, kz),
                    "execute if score #key le.gd matches 1 if loaded %d %d %d unless entity @e[type=minecraft:interaction,tag=le.gdkey,x=%.1f,y=%d,z=%.1f,distance=..2] run function last_ember:garden/gen/key_build" % (kx, ky, kz, kx + 0.5, ky, kz + 0.5)])
    w("key_fx", [hdr + "the key is taken",
                 "playsound minecraft:block.creaking_heart.spawn block @a[distance=..24] %d %d %d 1 0.7" % (kx, ky, kz),
                 "particle minecraft:block_crumble{block_state:\"minecraft:pale_oak_wood\"} %.1f %.1f %.1f 0.3 0.3 0.3 0 30 force" % (kx + 0.5, ky + 0.8, kz + 0.5)])
    sx, sy, sz = meta["stand"]
    pieces = [("feet", "boots"), ("legs", "leggings"), ("chest", "chestplate"), ("head", "helmet")]
    w("stand_build", [hdr + "the show stand of the Creaking armour (nothing can be taken or put: DisabledSlots, set after the pieces: a disabled slot refuses commands too) and its click box",
                      "kill @e[type=minecraft:armor_stand,tag=le.gdstand]", "kill @e[type=minecraft:interaction,tag=le.gdarm]",
                      'summon minecraft:armor_stand %.1f %d %.1f {Tags:["le.gdstand","le.npc"],Rotation:[0f,0f],Invulnerable:1b,NoGravity:1b,ShowArms:1b,PersistenceRequired:1b}' % (sx + 0.5, sy, sz + 0.5)] +
                     ["loot replace entity @e[type=minecraft:armor_stand,tag=le.gdstand,limit=1] armor.%s loot last_ember:item/creaking_%s" % (s_, p) for s_, p in pieces] +
                     ["data merge entity @e[type=minecraft:armor_stand,tag=le.gdstand,limit=1] {DisabledSlots:4144959}",
                      'summon minecraft:interaction %.1f %d %.1f {Tags:["le.gdarm"],width:1.0f,height:2.05f,response:1b}' % (sx + 0.5, sy, sz + 0.5),
                      "scoreboard players set #stand le.gd 1"])
    w("stand_check", [hdr + "every second: the stand is there (built once per start when its chunk is loaded, rebuilt when it is missing)",
                      "execute if score #stand le.gd matches 1 if loaded %d %d %d unless entity @e[type=minecraft:armor_stand,tag=le.gdstand,x=%.1f,y=%d,z=%.1f,distance=..2] run scoreboard players set #stand le.gd 0" % (sx, sy, sz, sx + 0.5, sy, sz + 0.5),
                      "execute if score #stand le.gd matches 0 if loaded %d %d %d run function last_ember:garden/gen/stand_build" % (sx, sy, sz)])
    w("markers", [hdr + "mechanic points of the garden (storage only)",
                  "data modify storage last_ember:r1 m.garden_key set value [%d,%d,%d]" % (kx, ky, kz),
                  "data modify storage last_ember:r1 m.garden_stand set value [%d,%d,%d]" % (sx, sy, sz),
                  "data modify storage last_ember:r1 m.garden_door set value [%d,%d,%d]" % (dx, dy, dz)])
    # the door advancement (any use of the door block)
    adv = os.path.join(R.DP, "advancement/garden"); os.makedirs(adv, exist_ok=True)
    import json
    json.dump({"criteria": {"door": {"trigger": "minecraft:default_block_use", "conditions": {"location": {"type": "minecraft:location_check",
               "predicate": {"position": {"x": {"min": dx, "max": dx + 0.999}, "y": {"min": dy, "max": dy + 1.999}, "z": {"min": dz, "max": dz + 0.999}}}}}}},
               "rewards": {"function": "last_ember:garden/door_use"}}, open(os.path.join(adv, "door.json"), "w"), indent=1)
